let allData = {{workflowparams:allData}}
const updatedSM = []
const saveAs = {{workflowparams:saveAs}}

if (saveAs === "Cancelled") {
  const rawData = {{node:get_node_czmdH3Jw.data.data}}
  allData = Array.isArray(rawData) ? rawData[0] : rawData
}

const normalizeCategory = (cat) => {
  if (cat === "UNR") return "Unrestricted"
  if (cat === "BLK") return "Blocked"
  return cat
}

for (const [index, smLineItem] of allData.stock_movement.entries()) {
  smLineItem.organization_id = allData.organization_id;
  smLineItem.issuing_plant = allData.issuing_operation_faci || null;
  smLineItem.receiving_plant = allData.receiving_operation_faci || null;
  smLineItem.line_index = index + 1;

  smLineItem.category = normalizeCategory(smLineItem.category)

  if (smLineItem.temp_qty_data) {
    try {
      const parsed = JSON.parse(smLineItem.temp_qty_data)
      if (Array.isArray(parsed)) {
        for (const row of parsed) {
          row.category = normalizeCategory(row.category)
        }
        smLineItem.temp_qty_data = JSON.stringify(parsed)
      }
    } catch (e) {
      // leave as-is if not valid JSON
    }
  }

  updatedSM.push(smLineItem)
}

allData.stock_movement = updatedSM

if ({{workflowparams:pageStatus}} === "Add") {
  allData.stock_movement_status = "Draft"
}

if (saveAs === "Draft") {
  if(allData.stock_movement_no_type !== -9999 && (
  !allData.stock_movement_no || allData.stock_movement_no === null || allData.stock_movement_no === ''
)) {
  allData.stock_movement_no = 'draft'
  }
} else {
  if (
  allData.stock_movement_no_type !== -9999 &&
  (!allData.stock_movement_no ||
    allData.stock_movement_no === null ||
    allData.stock_movement_no === "" ||
    allData.stock_movement_status !== "In Progress")
) {
  allData.stock_movement_no = 'issued'
  }
}

// On cancel, flag the still-issued document number with a -Cancelled suffix
// (matches the GD/PP/SO cancel convention) so the number is visually flagged
// and freed for reuse. Idempotent. Runs before the cancel compute reads
// stock_movement_no for the reversal movements' trx_no, so those carry it too.
if (
  saveAs === "Cancelled" &&
  typeof allData.stock_movement_no === "string" &&
  allData.stock_movement_no &&
  !allData.stock_movement_no.endsWith("-Cancelled")
) {
  allData.stock_movement_no = allData.stock_movement_no + "-Cancelled";
}

return {
  allData: allData,
  stock_movement_status: allData.stock_movement_status,
  is_production_order: allData.is_production_order
}

return {
  required_fields: JSON.stringify([
  { name: "stock_movement_no", label: "Stock Movement No" },
  { name: "movement_type", label: "Movement Type" },
  { name: "issue_date", label: "Issue Date" },
  { name: "issuing_operation_faci", label: "Issuing Operation Facility" },
  {
    name: "stock_movement",
    label: "Item Information",
    isArray: true,
    arrayType: "object",
    arrayFields: [],
  },
]),
  data: JSON.stringify({
    stock_movement_no: {{node:code_node_yPlLXIZW.data.allData.stock_movement_no}},
    movement_type: {{node:code_node_yPlLXIZW.data.allData.movement_type}},
    issue_date: {{node:code_node_yPlLXIZW.data.allData.issue_date}},
    issuing_operation_faci: {{node:code_node_yPlLXIZW.data.allData.issuing_operation_faci}},
    stock_movement: {{node:code_node_yPlLXIZW.data.allData.stock_movement}}
  })
}

const saveAs = {{workflowparams:saveAs}};
const pageStatus = {{workflowparams:pageStatus}};

const rows = {{node:search_node_LOTspLive.data.data}};
const arr = Array.isArray(rows) ? rows : (rows ? [rows] : []);

// Draft/Completed/Cancelled pickings are not work in progress. Anything else is a
// picker's open work list, and the movement has no reconcile path -- editing it
// would leave the two out of step -- so block BEFORE anything is persisted.
// Only the "Created" re-save is gated: advancing or cancelling the movement stays
// open, and the auto-advance call from STOCK_PICKING_PROCESS sends "In Progress",
// so it exempts itself.
const active = arr.filter((p) => p &&
  p.sp_status !== "Draft" && p.sp_status !== "Completed" && p.sp_status !== "Cancelled");

let blocked = 0;
let guardMessage = "";
if (saveAs === "Created" && pageStatus === "Edit" && active.length > 0) {
  blocked = 1;
  const list = active.map((p) => p.sp_id || p.id).slice(0, 5).join(", ");
  const more = active.length > 5 ? " (+" + (active.length - 5) + " more)" : "";
  guardMessage =
    "Cannot edit this Location Transfer while " + active.length +
    (active.length === 1 ? " Stock Picking is" : " Stock Pickings are") +
    " active: " + list + more + ". Cancel or complete " +
    (active.length === 1 ? "it" : "them") + " first.";
}

return { blocked: blocked, guardMessage: guardMessage };

const allData = {{node:code_node_yPlLXIZW.data.allData}}
const subformData = allData.stock_movement || []

let locationFailed = 0;
let quantityFailed = 0
let locationMessage
let quantityMessage

const hasValidBalance = (tempData) => {
  if (!tempData) return false;
  try {
    const parsed = JSON.parse(tempData);
    return Array.isArray(parsed) && parsed.some(
      (entry) => entry.sm_quantity && parseFloat(entry.sm_quantity) > 0
    );
  } catch (e) {
    return false;
  }
};

for (let i = 0; i < subformData.length; i++) {
  const item = subformData[i];
  // Skip empty lines (no quantity selected) so they don't false-fail location validation
  if (!hasValidBalance(item.temp_qty_data)) continue;
  if (!item.location_id) {
    locationFailed = 1;
    locationMessage = `Location ID is required for item ${i + 1} in Location Transfer`
    break;
  }
}

const hasQuantity = subformData.some((line) => hasValidBalance(line.temp_qty_data));

if (!hasQuantity) {
  quantityFailed = 1
  quantityMessage = 'No quantity selected to transfer'
}

return {
  locationFailed: locationFailed,
  quantityFailed: quantityFailed,
  locationMessage: locationMessage,
  quantityMessage: quantityMessage
};

const roundQty = (v) => parseFloat(parseFloat(v || 0).toFixed(3));
const qtyStr = (v) => Math.max(0, roundQty(v)).toFixed(3);

const allData = {{node:code_node_yPlLXIZW.data.allData}};
const openRaw = {{node:search_node_LOTitOpenCancel.data.data}};
const openRows = Array.isArray(openRaw) ? openRaw : (openRaw ? [openRaw] : []);

const lines = allData.stock_movement || [];
const movements = [];
const materialSet = {};

// Cancel reverses the In-Progress staged state: subtract In Transit at the
// destination bin (relocated; was source), add the ORIGINAL category back at the
// source bin (fix: the old workflow hardcoded "Unrestricted").
for (const line of lines) {
  const D = line.location_id;
  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
  for (const e of entries) {
    const qty = roundQty(e.sm_quantity);
    if (qty <= 0) continue;
    const mat = e.material_id || line.item_selection;
    materialSet[mat] = true;
    movements.push({
      material_id: mat,
      batch_id: e.batch_id || null,
      quantity: qty,
      material_uom: e.material_uom || line.quantity_uom,
      subtractCategory: "In Transit",
      subtractLocation: D,
      addCategory: e.category || "Unrestricted",
      addLocation: e.location_id,
      handling_unit_id: e.handling_unit_id || null,
      manufacturing_date: e.manufacturing_date || null,
      expired_date: e.expired_date || null,
    });
  }
}

const transitUpdates = [];
for (const r of openRows) {
  if (r.status !== "In Transit") continue;
  transitUpdates.push({ id: r.id, open_qty: qtyStr(0), status: "Cancelled" });
}

return {
  movements,
  movementsLength: movements.length,
  transitUpdates,
  hasTransitUpdates: transitUpdates.length > 0 ? 1 : 0,
  materialIds: Object.keys(materialSet),
  plant_id: allData.issuing_operation_faci,
  organization_id: allData.organization_id,
  stock_movement_no: allData.stock_movement_no,
  doc_date: allData.issue_date,
};

return {
  cacheKey: {{system:uuid}}
}

const movements = {{node:code_node_LOTcancelCompute.data.movements}} || [];
const idxRaw = {{node:get_cache_node_LOTcancelIdx.data}};
const index = idxRaw ? parseInt(idxRaw, 10) : 0;
const m = movements[index] || {};

const itemsRaw = {{node:search_node_LOTitItemsCancel.data.data}} || [];
const items = Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw];
const itemData = items.find((i) => i && String(i.id) === String(m.material_id)) || null;

return {
  material_id: m.material_id,
  batch_id: m.batch_id || null,
  quantity: m.quantity,
  material_uom: m.material_uom,
  subtractCategory: m.subtractCategory,
  subtractLocation: m.subtractLocation,
  addCategory: m.addCategory,
  addLocation: m.addLocation,
  handling_unit_id: m.handling_unit_id || null,
  manufacturing_date: m.manufacturing_date || null,
  expired_date: m.expired_date || null,
  itemData: itemData,
  index: index,
  nextIndex: index + 1,
};

const roundQty = (v) => parseFloat(parseFloat(v || 0).toFixed(3));
const allData = {{node:code_node_yPlLXIZW.data.allData}};
const lines = allData.stock_movement || [];

// Source-availability guard on the Draft departure. Aggregate demand per unique
// (material, source bin, batch, category, uom) across ALL lines, then check each
// once with the SUMMED qty. This closes the stateless-per-line hole where two
// lines drawing the same source balance each passed a check the sum would fail.
const map = {};
for (const line of lines) {
  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
  for (const e of entries) {
    const qty = roundQty(e.sm_quantity);
    if (qty <= 0) continue;
    const mat = e.material_id || line.item_selection;
    const uom = e.material_uom || line.quantity_uom;
    const cat = e.category || "Unrestricted";
    const key = mat + "|" + e.location_id + "|" + (e.batch_id || "") + "|" + cat + "|" + uom;
    if (map[key]) map[key].quantity = roundQty(map[key].quantity + qty);
    else map[key] = {
      material_id: mat, location_id: e.location_id, batch_id: e.batch_id || null,
      category: cat, material_uom: uom, quantity: qty,
    };
  }
}

const aggregated = Object.values(map);
return {
  aggregated,
  aggLength: aggregated.length,
  plant_id: allData.issuing_operation_faci,
  organization_id: allData.organization_id,
};

return {
  cacheKey: {{system:uuid}}
}

const aggregated = {{node:code_node_LOTprecheckAgg.data.aggregated}} || [];
const idxRaw = {{node:get_cache_node_LOTprecheckIdx.data}};
const index = idxRaw ? parseInt(idxRaw, 10) : 0;
const b = aggregated[index] || {};
return {
  material_id: b.material_id,
  location_id: b.location_id,
  batch_id: b.batch_id || null,
  category: b.category,
  material_uom: b.material_uom,
  quantity: b.quantity,
  index: index,
  nextIndex: index + 1,
};

const subFormData = {{node:code_node_yPlLXIZW.data.allData.stock_movement}}

let isNotEqual = 0;

for (const sm of subformData) {
  if (sm.total_quantity !== sm.requested_qty) {
    isNotEqual = 1;
    break;
  }
}

return {
  isNotEqual: isNotEqual,
};

const roundQty = (v) => parseFloat(parseFloat(v || 0).toFixed(3));
const qtyStr = (v) => Math.max(0, roundQty(v)).toFixed(3);
// The ledger stores 3dp; at or under this a reconcile shortfall is a rounding
// artefact, not a real shortage. Matches code_node_LOTmainCompute.
const QTY_EPS = 0.005;

const currentData = {{node:code_node_yPlLXIZW.data.allData}};
const initialData = {{node:get_node_Ij7YbXCA.data.data}} || {};
const openRaw = {{node:search_node_LOTitOpenRecon.data.data}};
const openRows = Array.isArray(openRaw) ? openRaw : (openRaw ? [openRaw] : []);

const ctx = {
  docId: currentData.id || "",
  docNo: currentData.stock_movement_no || "",
  plantId: currentData.issuing_operation_faci,
  orgId: currentData.organization_id,
  docDate: currentData.issue_date,
};

// A Created document holds its stock as Reserved at the source bin, not as In
// Transit at the destination, so this transit reconcile must not run for it.
// code_node_LOTmainCompute rebuilds the reservation set instead (phase RESERVE).
const preStatus = {{node:code_node_yPlLXIZW.data.stock_movement_status}};
if (preStatus === "Created") {
  return {
    isDifferent: 0, movements: [], movementsLength: 0,
    transitCreates: [], hasTransitCreates: 0,
    transitUpdates: [], hasTransitUpdates: 0,
    shortages: [], hasShortage: 0, materialIds: [],
    plant_id: ctx.plantId, organization_id: ctx.orgId,
    stock_movement_no: ctx.docNo, doc_date: ctx.docDate,
  };
}

const lineStaging = (line) => {
  const D = line.location_id;
  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
  const byKey = {};
  for (const e of entries) {
    const qty = roundQty(e.sm_quantity); if (qty <= 0) continue;
    const mat = e.material_id || line.item_selection;
    const k = `${mat}|${e.location_id}|${e.batch_id || ""}|${e.category || "Unrestricted"}`;
    if (byKey[k]) byKey[k].qty = roundQty(byKey[k].qty + qty);
    else byKey[k] = { material_id: mat, source: e.location_id, batch_id: e.batch_id || null,
      category: e.category || "Unrestricted", qty, material_uom: e.material_uom || line.quantity_uom,
      handling_unit_id: e.handling_unit_id || null, manufacturing_date: e.manufacturing_date || null,
      expired_date: e.expired_date || null };
  }
  return { D, byKey };
};

const initLines = {}; for (const l of (initialData.stock_movement || [])) if (l.id) initLines[l.id] = l;
const curLines = {}; for (const l of (currentData.stock_movement || [])) if (l.id) curLines[l.id] = l;
const allIds = Object.keys(initLines).concat(Object.keys(curLines).filter(x => !initLines[x]));

const movements = [];
const materialSet = {};
const transitDelta = new Map();
const bumpTransit = (mat, batch, bin, delta, meta) => {
  const k = `${mat}|${batch || ""}|${bin}`;
  const cur = transitDelta.get(k);
  if (cur) cur.delta = roundQty(cur.delta + delta);
  else transitDelta.set(k, { delta: roundQty(delta), material: mat, batch: batch || null, bin, meta });
};
const pushPair = (base, subCat, subLoc, addCat, addLoc, qty) => {
  if (qty <= 0) return;
  materialSet[base.material_id] = true;
  movements.push({ material_id: base.material_id, batch_id: base.batch_id, quantity: roundQty(qty),
    material_uom: base.material_uom, handling_unit_id: base.handling_unit_id,
    manufacturing_date: base.manufacturing_date, expired_date: base.expired_date,
    subtractCategory: subCat, subtractLocation: subLoc, addCategory: addCat, addLocation: addLoc });
};

for (const id of allIds) {
  const init = initLines[id] ? lineStaging(initLines[id]) : null;
  const cur = curLines[id] ? lineStaging(curLines[id]) : null;

  if (init && cur && init.D !== cur.D) {
    const keys = {}; for (const k in init.byKey) keys[k] = 1; for (const k in cur.byKey) keys[k] = 1;
    for (const k in keys) {
      const a = cur.byKey[k], b = init.byKey[k]; const base = a || b;
      const cq = a ? a.qty : 0, iq = b ? b.qty : 0; const common = Math.min(cq, iq);
      if (common > 0) { pushPair(base, "In Transit", init.D, "In Transit", cur.D, common);
        bumpTransit(base.material_id, base.batch_id, init.D, -common, base);
        bumpTransit(base.material_id, base.batch_id, cur.D, +common, base); }
      if (cq > iq) { pushPair(base, base.category, base.source, "In Transit", cur.D, cq - iq);
        bumpTransit(base.material_id, base.batch_id, cur.D, +(cq - iq), base); }
      else if (iq > cq) { pushPair(base, "In Transit", init.D, base.category, base.source, iq - cq);
        bumpTransit(base.material_id, base.batch_id, init.D, -(iq - cq), base); }
    }
    continue;
  }

  const D = (cur || init).D;
  const keys = {};
  if (init) for (const k in init.byKey) keys[k] = 1;
  if (cur) for (const k in cur.byKey) keys[k] = 1;
  for (const k in keys) {
    const a = cur ? cur.byKey[k] : null, b = init ? init.byKey[k] : null; const base = a || b;
    const cq = a ? a.qty : 0, iq = b ? b.qty : 0; const d = roundQty(cq - iq);
    if (d > 0) { pushPair(base, base.category, base.source, "In Transit", D, d); bumpTransit(base.material_id, base.batch_id, D, +d, base); }
    else if (d < 0) { pushPair(base, "In Transit", D, base.category, base.source, -d); bumpTransit(base.material_id, base.batch_id, D, d, base); }
  }
}

const rows = openRows.filter((r) => r.status === "In Transit");
const byKey = new Map();
for (const r of rows) { const k = `${r.material_id}|${r.batch_id || ""}|${r.transit_bin}`; if (!byKey.has(k)) byKey.set(k, []); byKey.get(k).push(r); }
for (const [, l] of byKey) l.sort((a, b) => { const da = String(a.transit_date || ""), db = String(b.transit_date || ""); if (da !== db) return da < db ? -1 : 1; return (a.line_no || 0) - (b.line_no || 0); });

const transitUpdates = [], transitCreates = [], shortages = [];
// A Location Transfer staged before this ledger existed has no rows of any status
// (search_node_LOTitOpenRecon is deliberately unfiltered by status, so this means
// "never tracked", not "already consumed"). Writing rows for an edit delta would
// leave it half-tracked -- the tuple becomes tracked, but only for the delta,
// while completion still demands the full staged quantity, which is exactly the
// shortage 400 that code_node_LOTmainCompute's per-tuple skip exists to avoid.
// The inventory reconcile below still runs: only the ledger writes are suppressed,
// so movements/isDifferent are unaffected and a legacy document stays legacy.
const isLegacyDoc = openRows.length === 0;
for (const [k, info] of (isLegacyDoc ? [] : transitDelta)) {
  const delta = info.delta, material = info.material, batch = info.batch, bin = info.bin, meta = info.meta;
  if (delta === 0) continue;
  const list = byKey.get(k) || [];
  if (delta > 0) {
    if (list.length > 0) { const r = list[0]; const nq = roundQty(r.open_qty + delta);
      transitUpdates.push({ id: r.id, transit_qty: qtyStr(nq), open_qty: qtyStr(nq), status: "In Transit", received_date: null }); r.open_qty = nq; }
    else transitCreates.push({ doc_type: "Location Transfer", doc_id: ctx.docId, doc_no: ctx.docNo, doc_line_id: "", line_no: 0,
      parent_id: "", parent_no: "", parent_line_id: "", material_id: material, item_code: "", item_name: "", item_desc: "",
      item_uom: meta.material_uom, batch_id: batch, handling_unit_id: meta.handling_unit_id, plant_id: ctx.plantId,
      organization_id: ctx.orgId, transit_bin: bin, from_plant_id: ctx.plantId, from_bin: null, from_category: null,
      to_plant_id: ctx.plantId, to_bin: bin, to_category: "Unrestricted", transit_qty: qtyStr(delta), received_qty: qtyStr(0),
      open_qty: qtyStr(delta), status: "In Transit", transit_date: ctx.docDate, received_date: null, remark: "",
      target_doc_type: "Location Transfer", target_doc_id: ctx.docId, target_doc_no: ctx.docNo, target_doc_line_id: "", source_transit_id: "" });
  } else {
    let need = -delta;
    for (const r of list) { if (need <= 0) break; if (r.open_qty <= 0) continue; const take = roundQty(Math.min(r.open_qty, need)); const nq = roundQty(r.open_qty - take);
      transitUpdates.push({ id: r.id, transit_qty: qtyStr(nq), open_qty: qtyStr(nq), status: nq <= 0 ? "Cancelled" : "In Transit", received_date: null }); r.open_qty = nq; need = roundQty(need - take); }
    if (need > QTY_EPS) shortages.push({ material_id: material, batch_id: batch, bin, shortage: qtyStr(need) });
  }
}

return {
  isDifferent: movements.length > 0 ? 1 : 0,
  movements, movementsLength: movements.length,
  transitCreates, hasTransitCreates: transitCreates.length > 0 ? 1 : 0,
  transitUpdates, hasTransitUpdates: transitUpdates.length > 0 ? 1 : 0,
  shortages, hasShortage: shortages.length > 0 ? 1 : 0,
  materialIds: Object.keys(materialSet),
  plant_id: ctx.plantId, organization_id: ctx.orgId, stock_movement_no: ctx.docNo, doc_date: ctx.docDate,
};

const creates = {{node:code_node_uht83Wzh.data.transitCreates}} || [];
const itemsRaw = {{node:search_node_LOTitItemsRecon.data.data}} || [];
const items = Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw];
// The compute nodes build the ledger rows before items are fetched, so
// item_code/name/desc arrive empty. Fill them from the item master here.
const map = {};
for (const it of items) if (it && it.id) map[String(it.id)] = it;
const enrichedCreates = creates.map((c) => {
  const it = map[String(c.material_id)];
  if (!it) return c;
  return Object.assign({}, c, {
    item_code: it.material_code || "",
    item_name: it.material_name || "",
    item_desc: it.material_desc || "",
  });
});
return { enrichedCreates };

return {
  cacheKey: {{system:uuid}}
}

const movements = {{node:code_node_uht83Wzh.data.movements}} || [];
const idxRaw = {{node:get_cache_node_LOTreconIdx.data}};
const index = idxRaw ? parseInt(idxRaw, 10) : 0;
const m = movements[index] || {};
const itemsRaw = {{node:search_node_LOTitItemsRecon.data.data}} || [];
const items = Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw];
const itemData = items.find((i) => i && String(i.id) === String(m.material_id)) || null;
return {
  material_id: m.material_id, batch_id: m.batch_id || null, quantity: m.quantity,
  material_uom: m.material_uom, subtractCategory: m.subtractCategory, subtractLocation: m.subtractLocation,
  addCategory: m.addCategory, addLocation: m.addLocation, handling_unit_id: m.handling_unit_id || null,
  manufacturing_date: m.manufacturing_date || null, expired_date: m.expired_date || null,
  itemData: itemData, index: index, nextIndex: index + 1,
};

const pageStatus = {{workflowparams:pageStatus}};
let docId = "";
if (pageStatus === "Add") {
  const rd = {{node:add_node_xxQX3uMU.data}};
  const rec = Array.isArray(rd) ? rd[0] : rd;
  docId = (rec && rec.id) ? rec.id : "";
} else {
  docId = {{node:code_node_yPlLXIZW.data.allData.id}} || "";
}
return { docId: docId };

const roundQty = (v) => parseFloat(parseFloat(v || 0).toFixed(3));
const qtyStr = (v) => Math.max(0, roundQty(v)).toFixed(3);
// The ledger stores 3dp. A base -> alt -> base round trip on a fractional UOM
// conversion comes back high, so at or under this is a rounding artefact, not a
// real shortage, and must not 400 the completion.
const QTY_EPS = 0.005;

const page_status = {{workflowparams:pageStatus}};
const status = {{node:code_node_yPlLXIZW.data.stock_movement_status}};
const saveAs = {{workflowparams:saveAs}};

let allData;
if (page_status === "Add") {
  const rd = {{node:add_node_xxQX3uMU.data}};
  allData = Array.isArray(rd) ? rd[0] : rd;
} else if (page_status === "Edit" && (status === "Draft" || status === "Created")) {
  allData = {{node:get_node_lvTzXllZ.data.data}};
} else {
  allData = {{node:code_node_yPlLXIZW.data.allData}};
}

const openRaw = {{node:search_node_LOTitOpenMain.data.data}};
const openRows = Array.isArray(openRaw) ? openRaw : (openRaw ? [openRaw] : []);

// Open reservations this document already holds. Only "Allocated" rows carry
// live Reserved stock; Delivered/Cancelled rows are history.
const resRaw = {{node:search_node_LOTresOpenMain.data.data}};
const resAll = Array.isArray(resRaw) ? resRaw : (resRaw ? [resRaw] : []);
const resRows = resAll.filter((r) => r && r.status === "Allocated");

const lines = allData.stock_movement || [];

// doc_line_id fix (same class as GR): on a fresh (Add) save the add-node response
// carries no subform row ids, so line.id is empty. Re-read the persisted doc and
// resolve each line's id by its persisted line_index. (Edit+Draft already reads the
// persisted doc via get_node_lvTzXllZ, so this is a no-op there.)
const persistedRaw = {{node:get_node_LOTmainLines.data.data}};
const persistedRec = Array.isArray(persistedRaw) ? persistedRaw[0] : persistedRaw;
const persistedLines = (persistedRec && persistedRec.stock_movement) ? persistedRec.stock_movement : [];
const idByLineIdx = {};
persistedLines.forEach((r, i) => {
  const k = (r.line_index === undefined || r.line_index === null || r.line_index === "") ? String(i + 1) : String(r.line_index);
  if (r.id) idByLineIdx[k] = r.id;
});
const plantId = allData.issuing_operation_faci;
const orgId = allData.organization_id;
const docId = allData.id || "";
const docNo = allData.stock_movement_no || "";
const docDate = allData.issue_date;

// STAGE = Draft->In Progress; COMPLETE = In Progress->Completed; DIRECT = Draft->Completed
// RESERVE            = ->Created            : -C@S, +Reserved@S  (picking hold)
// STAGE_FROM_CREATED = Created->In Progress : -Reserved@S, +In Transit@D
// DIRECT_FROM_CREATED= Created->Completed   : -Reserved@S, +C@D  (defensive; the form
//                      hides Complete at Created when picking is required, but a
//                      plain DIRECT here would wrongly subtract C@S instead of Reserved@S)
const phase =
  saveAs === "Created" ? "RESERVE"
    : saveAs === "In Progress" && status === "Created" ? "STAGE_FROM_CREATED"
      : saveAs === "In Progress" && status === "Draft" ? "STAGE"
        : saveAs === "Completed" && status === "In Progress" ? "COMPLETE"
          : saveAs === "Completed" && status === "Created" ? "DIRECT_FROM_CREATED"
            : "DIRECT";

const RESERVED = "Reserved";
// on_reserved_gd.from_category records the category the stock was taken from, so the
// hold can be released back to it.
const fromCatOf = (r) => r.from_category || "Unrestricted";

const releaseMovements = [];
const movements = [];
const transitCreates = [];
const reserveCreates = [];
const reserveUpdates = [];
const materialSet = {};

// RESERVE is an idempotent rebuild: every open hold is released back to its source
// category first, then the whole set is re-reserved from the current lines. Editing a
// Created document therefore needs no delta reconcile.
if (phase === "RESERVE") {
  for (const r of resRows) {
    const q = roundQty(r.open_qty);
    if (q > 0) {
      materialSet[r.material_id] = true;
      releaseMovements.push({
        material_id: r.material_id, batch_id: r.batch_id || null, quantity: q,
        material_uom: r.item_uom, handling_unit_id: r.handling_unit_id || null,
        manufacturing_date: null, expired_date: null,
        subtractCategory: RESERVED, subtractLocation: r.bin_location,
        addCategory: fromCatOf(r), addLocation: r.bin_location,
      });
    }
    reserveUpdates.push({
      id: r.id, delivered_qty: qtyStr(r.delivered_qty), open_qty: qtyStr(0), status: "Cancelled",
    });
  }
}

// Leaving Created consumes every hold the document owns. The Subtract Inventory
// workflow is the real guard on quantity: if Reserved is short it 400s there.
if (phase === "STAGE_FROM_CREATED" || phase === "DIRECT_FROM_CREATED") {
  for (const r of resRows) {
    reserveUpdates.push({
      id: r.id,
      delivered_qty: qtyStr(roundQty(r.delivered_qty) + roundQty(r.open_qty)),
      open_qty: qtyStr(0),
      status: "Delivered",
    });
  }
}

for (const line of lines) {
  const D = line.location_id;
  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
  for (const e of entries) {
    const qty = roundQty(e.sm_quantity);
    if (qty <= 0) continue;
    const S = e.location_id;
    const C = e.category || "Unrestricted";
    const mat = e.material_id || line.item_selection;
    const batchId = e.batch_id || null;
    const hu = e.handling_unit_id || null;
    materialSet[mat] = true;
    const lineId = line.id || idByLineIdx[String(line.line_index)] || "";
    const base = {
      material_id: mat, batch_id: batchId, quantity: qty,
      material_uom: e.material_uom || line.quantity_uom, handling_unit_id: hu,
      manufacturing_date: e.manufacturing_date || null, expired_date: e.expired_date || null,
    };
    if (phase === "RESERVE") {
      // -C@S, +Reserved@S (stock does not move bin; it is held in place)
      movements.push({ ...base, subtractCategory: C, subtractLocation: S, addCategory: RESERVED, addLocation: S });
      reserveCreates.push({
        doc_type: "Location Transfer", doc_id: docId, doc_no: docNo, doc_line_id: lineId, line_no: line.line_index,
        parent_id: "", parent_no: "", parent_line_id: "",
        material_id: mat, item_code: "", item_name: "", item_desc: "", item_uom: base.material_uom,
        batch_id: batchId, handling_unit_id: hu, bin_location: S,
        reserved_qty: qtyStr(qty), delivered_qty: qtyStr(0), open_qty: qtyStr(qty),
        status: "Allocated", reserved_date: docDate, plant_id: plantId, organization_id: orgId,
        from_category: C, remark: line.item_remark || "", target_gd_id: "", source_reserved_id: "",
      });
    } else if (phase === "STAGE_FROM_CREATED") {
      // -Reserved@S, +InTransit@D (relocated to destination)
      movements.push({ ...base, subtractCategory: RESERVED, subtractLocation: S, addCategory: "In Transit", addLocation: D });
      transitCreates.push({
        doc_type: "Location Transfer", doc_id: docId, doc_no: docNo, doc_line_id: lineId,
        line_no: line.line_index, parent_id: "", parent_no: "", parent_line_id: "",
        material_id: mat, item_code: "", item_name: "", item_desc: "",
        item_uom: base.material_uom, batch_id: batchId, handling_unit_id: hu,
        plant_id: plantId, organization_id: orgId, transit_bin: D,
        from_plant_id: plantId, from_bin: S, from_category: C,
        to_plant_id: plantId, to_bin: D, to_category: C,
        transit_qty: qtyStr(qty), received_qty: qtyStr(0), open_qty: qtyStr(qty),
        status: "In Transit", transit_date: docDate, received_date: null, remark: line.item_remark || "",
        target_doc_type: "Location Transfer", target_doc_id: docId, target_doc_no: docNo,
        target_doc_line_id: lineId, source_transit_id: "",
      });
    } else if (phase === "DIRECT_FROM_CREATED") {
      // -Reserved@S, +C@D
      movements.push({ ...base, subtractCategory: RESERVED, subtractLocation: S, addCategory: C, addLocation: D });
    } else if (phase === "STAGE") {
      // -C@S, +InTransit@D (relocated to destination)
      movements.push({ ...base, subtractCategory: C, subtractLocation: S, addCategory: "In Transit", addLocation: D });
      transitCreates.push({
        doc_type: "Location Transfer", doc_id: docId, doc_no: docNo, doc_line_id: lineId,
        line_no: line.line_index, parent_id: "", parent_no: "", parent_line_id: "",
        material_id: mat, item_code: "", item_name: "", item_desc: "",
        item_uom: base.material_uom, batch_id: batchId, handling_unit_id: hu,
        plant_id: plantId, organization_id: orgId, transit_bin: D,
        from_plant_id: plantId, from_bin: S, from_category: C,
        to_plant_id: plantId, to_bin: D, to_category: C,
        transit_qty: qtyStr(qty), received_qty: qtyStr(0), open_qty: qtyStr(qty),
        status: "In Transit", transit_date: docDate, received_date: null, remark: line.item_remark || "",
        target_doc_type: "Location Transfer", target_doc_id: docId, target_doc_no: docNo,
        target_doc_line_id: lineId, source_transit_id: "",
      });
    } else if (phase === "COMPLETE") {
      // -InTransit@D (relocated), +C@D
      movements.push({ ...base, subtractCategory: "In Transit", subtractLocation: D, addCategory: C, addLocation: D });
    } else {
      // DIRECT: -C@S, +C@D
      movements.push({ ...base, subtractCategory: C, subtractLocation: S, addCategory: C, addLocation: D });
    }
  }
}

// ledger close on COMPLETE: consume this doc's open rows FIFO with a guard.
const transitUpdates = [];
const shortages = [];
if (phase === "COMPLETE") {
  const key = (m, b, d) => `${m || ""}|${b || ""}|${d || ""}`;
  // search_node_LOTitOpenMain returns EVERY row for this doc, any status, so two
  // structures come off it:
  //
  //   trackedTuples - every tuple this doc has ever staged. A tuple in here but
  //     absent from pool is fully consumed, so a second claim is a
  //     double-consumption and must 400.
  //   pool - open rows only. The FIFO stock actually available to draw down.
  //
  // A tuple in NEITHER is untracked: a Location Transfer staged before this
  // ledger existed holds In Transit stock at D with no rows behind it. Blocking
  // its completion would strand that stock, so those tuples fall through and the
  // inventory workflows behave as they always did. code_node_uht83Wzh refuses to
  // backfill such a document precisely so it cannot end up half-tracked.
  const trackedTuples = {};
  const pool = {};
  for (const r of openRows) {
    const k = key(r.material_id, r.batch_id, r.transit_bin);
    trackedTuples[k] = 1;
    if (r.status !== "In Transit") continue;
    if (!pool[k]) pool[k] = [];
    pool[k].push({ row: r, remaining: roundQty(r.open_qty), consumed: 0 });
  }
  for (const k in pool) pool[k].sort((a, b) => {
    const da = String(a.row.transit_date || ""), db = String(b.row.transit_date || "");
    if (da !== db) return da < db ? -1 : 1;
    return (a.row.line_no || 0) - (b.row.line_no || 0);
  });
  for (const m of movements) {
    const mk = key(m.material_id, m.batch_id, m.addLocation);
    // Untracked tuple: this document never staged this stock through the ledger.
    if (!trackedTuples[mk]) continue;
    let need = roundQty(m.quantity);
    const bucket = pool[mk] || [];
    for (const ent of bucket) {
      if (need <= 0) break;
      if (ent.remaining <= 0) continue;
      const take = roundQty(Math.min(ent.remaining, need));
      ent.remaining = roundQty(ent.remaining - take);
      ent.consumed = roundQty(ent.consumed + take);
      need = roundQty(need - take);
    }
    if (need > QTY_EPS) shortages.push({ material_id: m.material_id, batch_id: m.batch_id || "", bin: m.addLocation, shortage: qtyStr(need) });
  }
  for (const k in pool) for (const ent of pool[k]) {
    if (!ent.consumed) continue;
    const r = ent.row;
    transitUpdates.push({
      id: r.id,
      received_qty: qtyStr(roundQty((r.received_qty || 0) + ent.consumed)),
      open_qty: qtyStr(ent.remaining),
      status: ent.remaining <= 0 ? "Received" : "In Transit",
      received_date: ent.remaining <= 0 ? docDate : null,
    });
  }
}

// A category/bin pair that does not actually move (e.g. reserving stock already in
// Reserved) would otherwise emit a pointless subtract+add round trip.
const allMovements = releaseMovements.concat(movements).filter(
  (m) => !(m.subtractCategory === m.addCategory && String(m.subtractLocation) === String(m.addLocation))
);

return {
  phase, movements: allMovements, movementsLength: allMovements.length,
  transitCreates, hasTransitCreates: transitCreates.length > 0 ? 1 : 0,
  transitUpdates, hasTransitUpdates: transitUpdates.length > 0 ? 1 : 0,
  reserveCreates, hasReserveCreates: reserveCreates.length > 0 ? 1 : 0,
  reserveUpdates, hasReserveUpdates: reserveUpdates.length > 0 ? 1 : 0,
  shortages, hasShortage: shortages.length > 0 ? 1 : 0,
  materialIds: Object.keys(materialSet),
  plant_id: plantId, organization_id: orgId, stock_movement_no: docNo, doc_date: docDate,
};

const creates = {{node:code_node_LOTmainCompute.data.transitCreates}} || [];
const reserves = {{node:code_node_LOTmainCompute.data.reserveCreates}} || [];
const itemsRaw = {{node:search_node_LOTitItemsMain.data.data}} || [];
const items = Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw];
// The compute nodes build the ledger rows before items are fetched, so
// item_code/name/desc arrive empty. Fill them from the item master here.
const map = {};
for (const it of items) if (it && it.id) map[String(it.id)] = it;
const enrich = (rows) => rows.map((c) => {
  const it = map[String(c.material_id)];
  if (!it) return c;
  return Object.assign({}, c, {
    item_code: it.material_code || "",
    item_name: it.material_name || "",
    item_desc: it.material_desc || "",
  });
});
return { enrichedCreates: enrich(creates), enrichedReserves: enrich(reserves) };

return {
  cacheKey: {{system:uuid}}
}

const movements = {{node:code_node_LOTmainCompute.data.movements}} || [];
const idxRaw = {{node:get_cache_node_LOTmainIdx.data}};
const index = idxRaw ? parseInt(idxRaw, 10) : 0;
const m = movements[index] || {};
const itemsRaw = {{node:search_node_LOTitItemsMain.data.data}} || [];
const items = Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw];
const itemData = items.find((i) => i && String(i.id) === String(m.material_id)) || null;
return {
  material_id: m.material_id, batch_id: m.batch_id || null, quantity: m.quantity,
  material_uom: m.material_uom, subtractCategory: m.subtractCategory, subtractLocation: m.subtractLocation,
  addCategory: m.addCategory, addLocation: m.addLocation, handling_unit_id: m.handling_unit_id || null,
  manufacturing_date: m.manufacturing_date || null, expired_date: m.expired_date || null,
  itemData: itemData, index: index, nextIndex: index + 1,
};

const roundQty = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;
const qtyNum = (v) => Math.max(0, roundQty(v));

const saveAs = {{workflowparams:saveAs}};
const empty = { needsCreate: 0, createData: {}, srcIds: [], lineIds: [], pickingStatus: "" };
if (saveAs !== "Created") return empty;

const raw = {{node:get_node_LOTmainLines.data.data}};
const allData = Array.isArray(raw) ? raw[0] : raw;
if (!allData) return empty;

const docId = String(allData.id || "");
const docNo = allData.stock_movement_no || "";

// One Stock Picking per movement. The reservation rebuild above is idempotent,
// this is not -- an existing non-Cancelled picking short-circuits the build so a
// re-save of a Created document cannot mint a second one.
const existRaw = {{node:search_node_LOTspLive.data.data}};
const existAll = Array.isArray(existRaw) ? existRaw : (existRaw ? [existRaw] : []);
if (existAll.filter((p) => p && p.sp_status !== "Cancelled").length > 0) return empty;

const ruleRaw = {{node:get_node_LOTspRule.data.data}};
const rule = Array.isArray(ruleRaw) ? ruleRaw[0] : ruleRaw;
// -9999 is the platform's "no numbering rule" sentinel -- the same one
// StockPickingLoopWorkflow tests before it asks for a generated number. Without a
// "Stock Picking" prefix for this organisation the document is created unnumbered
// rather than not at all, so the pick is never silently lost.
const ruleId = rule && rule.id ? rule.id : -9999;

// One picking row per (item, batch, bin, movement line, HU) -- the same grouping the
// GD path uses, so two allocations that differ only by bin stay separately pickable.
const groups = new Map();
const lineIds = [];

for (const line of allData.stock_movement || []) {
  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
  let lineHasWork = 0;
  for (const e of entries) {
    const qty = qtyNum(e.sm_quantity);
    if (qty <= 0) continue;
    const mat = e.material_id || line.item_selection;
    if (!mat) continue;
    const uom = e.material_uom || line.quantity_uom;
    const key = [
      String(mat), String(e.batch_id || "no-batch"), String(e.location_id || "no-bin"),
      String(line.id || ""), String(e.handling_unit_id || "no-hu"),
    ].join("|");
    let g = groups.get(key);
    if (!g) {
      g = {
        row_type: "item", hu_select: 0,
        handling_unit_id: e.handling_unit_id || null,
        item_code: String(mat),
        item_name: line.item_name || "",
        item_desc: line.item_desc || "",
        more_desc: "",
        src_no: docNo,
        batch_no: e.batch_id || null,
        target_batch: null,
        qty_to_pick: 0, to_pick_alt: 0,
        pending_process_qty: 0, pending_alt: 0, picked_qty: 0,
        // Identity conversion. enrichPickingUOM() in SPonMounted recomputes both
        // scalars and both alt columns from the item master every time the Stock
        // Picking is opened, so seeding them 1:1 is correct rather than merely safe.
        order_base_qty: 1, picking_base_qty: 1,
        item_uom: uom, picking_uom: uom,
        source_bin: e.location_id || null,
        line_status: "Open",
        net_weight: 0, weight_conversion: 0,
        project_id: line.project_id || null,
        src_id: docId, src_line_id: String(line.id || ""),
        is_serialized_item: 0,
        serialList: [],
      };
      groups.set(key, g);
    }
    g.qty_to_pick = roundQty(g.qty_to_pick + qty);
    if (e.serial_number) g.serialList.push(String(e.serial_number));
    lineHasWork = 1;
  }
  if (lineHasWork && line.id) lineIds.push(String(line.id));
}

const tablePickingItems = [];
groups.forEach((g) => {
  g.pending_process_qty = g.qty_to_pick;
  g.to_pick_alt = g.qty_to_pick;
  g.pending_alt = g.qty_to_pick;
  if (g.serialList.length > 0) {
    g.is_serialized_item = 1;
    g.serial_numbers = g.serialList.join(", ");
  }
  delete g.serialList;
  tablePickingItems.push(g);
});

// Nothing allocated means nothing to pick -- a description-only document must not
// spawn an empty picking the warehouse can never complete.
if (tablePickingItems.length === 0) return empty;

const createData = {
  sp_status: "Created",
  sp_id: ruleId === -9999 ? "" : "issued",
  sp_id_type: ruleId,
  plant_id: allData.issuing_operation_faci,
  organization_id: allData.organization_id,
  movement_type: "Picking",
  ref_doc_type: "Location Transfer",
  src_id: docId,
  src_no: docNo,
  assigned_to: [],
  ref_doc: [],
  created_at: allData.issue_date,
  created_by: allData.issued_by || "",
  is_processing: 0,
  project_id: allData.project_id || null,
  remarks: allData.remarks || "",
  remarks_2: allData.remark2 || "",
  remarks_3: allData.remark3 || "",
  table_picking_items: tablePickingItems,
  table_picking_records: [],
};

return {
  needsCreate: 1, createData: createData,
  srcIds: [docId], lineIds: lineIds, pickingStatus: "Created",
};

const allData = {{node:code_node_yPlLXIZW.data.allData}};
const stockMovement = allData.stock_movement || [];
const plantId = allData.issuing_operation_faci;
const organizationId = allData.organization_id;

const huUpdatesMap = new Map();
for (const smRow of stockMovement) {
  if (!smRow.temp_qty_data) continue;
  if (!smRow.location_id || !smRow.storage_location_id) continue;
  let entries;
  try {
    entries = JSON.parse(smRow.temp_qty_data);
  } catch (e) {
    continue;
  }
  if (!Array.isArray(entries)) continue;
  for (const entry of entries) {
    const huId = entry.handling_unit_id;
    if (!huId) continue;
    if (huUpdatesMap.has(huId)) continue;
    huUpdatesMap.set(huId, {
      handling_unit_id: huId,
      plant_id: plantId,
      organization_id: organizationId,
      location_id: smRow.location_id,
      storage_location_id: smRow.storage_location_id,
    });
  }
}

return {
  huUpdates: Array.from(huUpdatesMap.values()),
  huUpdatesLength: huUpdatesMap.size,
};

const u = {{node:loop_ZCizlmVG}}

return {
  handling_unit_id: u.handling_unit_id,
  plant_id: u.plant_id,
  organization_id: u.organization_id,
  location_id: u.location_id,
  storage_location_id: u.storage_location_id,
};

const tableSM = {{node:code_node_yPlLXIZW.data.allData.stock_movement}}

const uniqueItemIds = [
  ...new Set(
    tableSM
      .filter((item) => item.item_selection)
      .map((item) => item.item_selection),
  ),
];

const date = new Date().toISOString();
const updates = [];

for (const itemId of uniqueItemIds) {
  updates.push({
    id: itemId,
    last_transaction_date: date,
  });
}

return {
  updates: updates,
};
